#include "wokwi-api.h"                                                                  // базовий апаратний інтерфейс користувацьких чіпів емулятора
#include <stdio.h>                                                                      // функції стандартного введення та виведення даних
#include <stdlib.h>                                                                     // функції виділення динамічної пам'яті мікросхеми
#include <string.h>                                                                     // маніпуляції з навігаційними рядковими даними

typedef struct {                                                                        // структура внутрішнього апаратного стану супутникового чіпа
  pin_t vcc;                                                                            // вивід живлення логічних кіл навігаційного приймача
  pin_t gnd;                                                                            // загальний вивід опорного потенціалу землі
  pin_t rx;                                                                             // вхідний вивід прийому конфігураційних послідовних даних
  pin_t tx;                                                                             // вихідний вивід передачі супутникових протокольних речень
  uart_dev_t uart;                                                                      // дескриптор апаратного послідовного порту мікросхеми
  timer_t timer;                                                                        // дескриптор періодичного системного таймера формування пакетів
  uint32_t speed_attr;                                                                  // дескриптор керованого повзунком атрибута шляхової швидкості
} chip_state_t;                                                                         // визначення користувацького типу стану мікросхеми

static void on_timer(void *user_data) {                                                 // періодичний обробник генерації супутникових навігаційних речень
  chip_state_t *chip = (chip_state_t *)user_data;                                       // приведення вказівника користувацьких даних до структури стану
  uint32_t speed_kmh = attr_read(chip->speed_attr);                                     // зчитування поточної швидкості з інтерактивного повзунка чіпа
  float speed_knots = (float)speed_kmh / 1.852f;                                        // переведення значення швидкості з кілометрів за годину у морські вузли
  char rmc[128];                                                                        // буфер формування навігаційного речення рекомендованих даних
  snprintf(rmc, sizeof(rmc),                                                            // форматування базової частини рядка рекомендованого мінімуму
           "$GPRMC,123519.00,A,5027.0900,N,03031.4700,E,%05.1f,084.4,230326,003.1,W",   // передача координат дати курсу та розрахованої швидкості
           speed_knots);                                                                // підстановка розрахованої швидкості руху у вузлах
  uint8_t cs = 0;                                                                       // змінна розрахунку стандартної контрольної суми протоколу
  for (int i = 1; rmc[i] != '\0'; i++) {                                                // побайтовий обхід навігаційного рядка між стартовим та кінцевим символами
    cs ^= (uint8_t)rmc[i];                                                              // операція порозрядного виключального або для кожного символу
  }                                                                                     // завершення циклу підрахунку контрольної суми
  char buf[160];                                                                        // буфер фінального пакету з контрольною сумою та закінченням рядка
  int len = snprintf(buf, sizeof(buf), "%s*%02X\r\n", rmc, cs);                         // додавання контрольної суми та маркерів кінця послідовності
  uart_write(chip->uart, (uint8_t *)buf, len);                                          // передача сформованого речення через вихідний послідовний інтерфейс
  char gga[128];                                                                        // буфер навігаційного речення фіксації глобального положення
  snprintf(gga, sizeof(gga),                                                            // форматування навігаційного речення параметрів якості фіксації
           "$GPGGA,123519.00,5027.0900,N,03031.4700,E,1,08,0.9,150.0,M,46.9,M,,");      // запис супутникових координат висоти та кількості супутників
  cs = 0;                                                                               // скидання контрольної суми перед розрахунком другого рядка
  for (int i = 1; gga[i] != '\0'; i++) {                                                // побайтовий прохід символів речення фіксації положення
    cs ^= (uint8_t)gga[i];                                                              // накопичення контрольної суми речення через виключальне або
  }                                                                                     // завершення обчислення контрольної суми рядка супутників
  len = snprintf(buf, sizeof(buf), "%s*%02X\r\n", gga, cs);                             // формування повного тексту речення супутників із закінченням
  uart_write(chip->uart, (uint8_t *)buf, len);                                          // відправка речення супутників через апаратний інтерфейс
}                                                                                       // завершення обробника періодичного таймера супутникового модуля

void chip_init(void) {                                                                  // головна початкова функція реєстрації та конфігурації чіпа
  chip_state_t *chip = (chip_state_t *)malloc(sizeof(chip_state_t));                    // динамічне виділення пам'яті під структуру стану екземпляра чіпа
  memset(chip, 0, sizeof(chip_state_t));                                                // очищення виділеної оперативної пам'яті початковими нулями
  chip->vcc = pin_init("VCC", INPUT);                                                   // реєстрація лінії позитивного потенціалу живлення чіпа
  chip->gnd = pin_init("GND", INPUT);                                                   // реєстрація лінії спільного нульового потенціалу схеми
  chip->rx = pin_init("RX", INPUT);                                                     // ініціалізація виводу прийому командних повідомлень
  chip->tx = pin_init("TX", OUTPUT_HIGH);                                               // ініціалізація вихідної лінії передачі даних у високому стані
  chip->speed_attr = attr_init("speed", 0);                                             // прив'язка керованого повзунком атрибута з початковою швидкістю
  const uart_config_t uart_cfg = {                                                      // конфігурація робочих параметрів послідовного інтерфейсу чіпа
    .rx = chip->rx,                                                                     // прив'язка фізичного виводу прийому вхідних байтів
    .tx = chip->tx,                                                                     // прив'язка фізичного виводу трансляції навігаційних речень
    .baud_rate = 9600,                                                                  // штатна швидкість послідовного інтерфейсу обміну даними
    .rx_data = NULL,                                                                    // відсутність обробника вхідних даних за ненадібністю
    .write_done = NULL,                                                                 // відсутність зворотного виклику завершення запису
    .user_data = chip,                                                                  // передача вказівника на внутрішній контекст даного чіпа
  };                                                                                    // завершення структури конфігурації послідовного порту
  chip->uart = uart_init(&uart_cfg);                                                    // ініціалізація та запуск логічного послідовного драйвера
  const timer_config_t timer_cfg = {                                                    // налаштування параметрів періодичного таймера генерації речень
    .callback = on_timer,                                                               // функція періодичного зворотного виклику відліку часу
    .user_data = chip,                                                                  // передача контексту чіпа в періодичний обробник події
  };                                                                                    // завершення структури налаштування системного таймера
  chip->timer = timer_init(&timer_cfg);                                                 // запуск апаратного таймера з визначеними параметрами
  timer_start(chip->timer, 1000000, true);                                              // встановлення періоду повторення одна секунда у циклічному режимі
}                                                                                       // завершення головної функції конфігурації мікросхеми